sql_query:
SELECT "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Follow-up duration for primary endpoint(s) in months | Overall", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Follow-up duration for primary endpoint(s) in months | Overall" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Follow-up duration for primary endpoint(s) in months | Overall", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_followup_bucket(source_value) AS "followup_bucket"
FROM base;
